<?php
declare(strict_types=1);
function payfast_gateway(): ?array {$q=db()->prepare("SELECT * FROM payment_gateways WHERE code='payfast' AND enabled=1 LIMIT 1");$q->execute();return $q->fetch()?:null;}
function payfast_get_token(array $gateway,array $order): string {if(!function_exists('curl_init'))throw new RuntimeException('PHP cURL extension is required for PayFast.');foreach(['merchant_id','secured_key','token_url'] as $k)if(trim((string)($gateway[$k]??''))==='')throw new RuntimeException('PayFast '.$k.' is not configured.');$fields=['MERCHANT_ID'=>$gateway['merchant_id'],'SECURED_KEY'=>$gateway['secured_key'],'BASKET_ID'=>$order['reference'],'TXNAMT'=>(string)$order['amount'],'CURRENCY_CODE'=>'PKR'];$ch=curl_init((string)$gateway['token_url']);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($fields),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>30,CURLOPT_USERAGENT=>'ShahkotPK-PayFast/2.0',CURLOPT_HTTPHEADER=>['Content-Type: application/x-www-form-urlencoded']]);$response=curl_exec($ch);$error=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($response===false||$code>=400)throw new RuntimeException('PayFast token request failed: '.($error?:'HTTP '.$code));$data=json_decode($response,true);$token=(string)($data['ACCESS_TOKEN']??$data['token']??'');if($token==='')throw new RuntimeException('PayFast did not return an access token.');return $token;}
function payfast_checkout_payload(array $g,array $o,string $token): array {$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$base=$scheme.'://'.($_SERVER['HTTP_HOST']??'localhost');$merchantName=$g['merchant_name']?:setting('site_name','ShahkotPK');$signature=md5($g['merchant_id'].':'.$merchantName.':'.$o['amount'].':'.$o['reference']);return ['CURRENCY_CODE'=>'PKR','MERCHANT_ID'=>$g['merchant_id'],'MERCHANT_NAME'=>$merchantName,'TOKEN'=>$token,'PROCCODE'=>'00','TXNAMT'=>$o['amount'],'CUSTOMER_MOBILE_NO'=>$o['user_phone']?:'03000000000','CUSTOMER_EMAIL_ADDRESS'=>$o['user_email']?:setting('support_email','no-reply@example.com'),'SIGNATURE'=>$signature,'VERSION'=>'SHAHKOTPK-2.0','TXNDESC'=>'ShahkotPK '.$o['purpose'].' payment','SUCCESS_URL'=>$base.'/payment-return.php?result=success','FAILURE_URL'=>$base.'/payment-return.php?result=failure','BASKET_ID'=>$o['reference'],'ORDER_DATE'=>date('Y-m-d H:i:s'),'CHECKOUT_URL'=>$base.'/payment-return.php?ipn=1','TRAN_TYPE'=>'ECOMM_PURCHASE'];}
function payfast_verify_response(array $g,array $p): bool {$basket=(string)($p['basket_id']??$p['BASKET_ID']??'');$err=(string)($p['err_code']??$p['ERR_CODE']??$p['RESPONSE_CODE']??$p['response_code']??'');$received=(string)($p['validation_hash']??$p['VALIDATION_HASH']??$p['SECURED_HASH']??$p['secured_hash']??'');if($basket===''||!in_array($err,['000','00'],true))return false;if($received!==''){$expected=hash('sha256',$basket.'|'.$g['secured_key'].'|'.$g['merchant_id'].'|'.$err);if(!hash_equals(strtolower($expected),strtolower($received)))return false;}return true;}
